import{_ as a,c as i,o as n,b0 as e}from"./chunks/framework.BWMBvyU7.js";const o=JSON.parse('{"title":"LV120-命令包","description":null,"frontmatter":{"title":"LV120-命令包","date":"2026-03-10T15:58:19.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/makefile/126d3897022b1cf2f9784013","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-10T15:58:19.463Z","fulluuid":"2f9784013d174d97ab08f7add13460d1","useduuid":"2f9784013"}},"headers":[],"relativePath":"sdoc/Language/makefile/126d3897022b1cf2f9784013.md","filePath":"sdoc/01-编程语言/15-Makefile/LV120-命令包.md","lastUpdated":1773672539000}'),l={name:"sdoc/Language/makefile/126d3897022b1cf2f9784013.md"};function p(t,s,h,r,k,d){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="lv120-命令包" tabindex="-1">LV120-命令包 <a class="header-anchor" href="#lv120-命令包" aria-label="Permalink to &quot;LV120-命令包&quot;">​</a></h1><p>在 Makefile 中，如果出现一些重复的命令序列，我们可以将这些命令定义成一个可重用的命令包（也称为命令模板）。这样可以提高 Makefile 的可读性和维护性。</p><h2 id="一、命令包简介" tabindex="-1">一、命令包简介 <a class="header-anchor" href="#一、命令包简介" aria-label="Permalink to &quot;一、命令包简介&quot;">​</a></h2><h3 id="_1-命令包的定义" tabindex="-1">1. 命令包的定义 <a class="header-anchor" href="#_1-命令包的定义" aria-label="Permalink to &quot;1. 命令包的定义&quot;">​</a></h3><p>定义命令包的语法以 <code>define</code> 开始，以 <code>endef</code> 结束，如：</p><div class="language-makefile vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run-yacc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">yacc </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">firstword</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $^</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mv y.tab.c </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endef</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这里，<code>run-yacc</code> 是这个命令包的名字，不要与 Makefile 中的变量重名。在 <code>define</code> 和 <code>endef</code> 之间的多行内容就是命令序列。这个命令包中的第一个命令是运行 Yacc 程序，因为 Yacc 程序总是生成 <code>y.tab.c</code> 的文件，所以第二行的命令就是把这个文件重命名。</p><h3 id="_2-命令包的使用" tabindex="-1">2. 命令包的使用 <a class="header-anchor" href="#_2-命令包的使用" aria-label="Permalink to &quot;2. 命令包的使用&quot;">​</a></h3><p>我们放到一个示例中来看看：</p><div class="language-makefile vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foo.c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : foo.y</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run-yacc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>我们可以看到，要使用这个命令包，我们就像使用变量一样。在这个命令包的使用中，命令包 <code>run-yacc</code> 中的 <code>$^</code> 就是 <code>foo.y</code>，<code>$@</code> 就是 <code>foo.c</code>。Make 在执行命令包时，命令包中的每个命令会被依次独立执行。</p><h3 id="_3-命令包的特点" tabindex="-1">3. 命令包的特点 <a class="header-anchor" href="#_3-命令包的特点" aria-label="Permalink to &quot;3. 命令包的特点&quot;">​</a></h3><p>（1）<strong>变量替换</strong>：命令包中的变量在使用时会自动替换为实际值（如 <code>$^</code>、<code>$@</code> 等自动化变量）。</p><p>（2）<strong>命令独立执行</strong>：命令包中的每个命令都会被独立执行，就像写在目标规则中的命令一样。</p><p>（3）<strong>可重用性</strong>：可以多次在不同的规则中使用同一个命令包。</p><h3 id="_4-注意事项" tabindex="-1">4. 注意事项 <a class="header-anchor" href="#_4-注意事项" aria-label="Permalink to &quot;4. 注意事项&quot;">​</a></h3><p>（1）<strong>变量名冲突</strong>：命令包名称不能与 Makefile 中的变量名重名。</p><p>（2）<strong>自动化变量</strong>：命令包中的自动化变量（如 <code>$^</code>、<code>$@</code>）在使用时会被自动替换为对应的实际值。</p><p>（3）<strong>命令执行</strong>：命令包中的每个命令都会被独立执行，具有与规则中直接书写的命令相同的语义。</p><p>（4）<strong>缩进规则</strong>：命令包内部的命令必须按照 Makefile 的缩进规则进行缩进（使用 Tab 键）。</p><h2 id="二、实际应用示例" tabindex="-1">二、实际应用示例 <a class="header-anchor" href="#二、实际应用示例" aria-label="Permalink to &quot;二、实际应用示例&quot;">​</a></h2><p>下面是一个更复杂的命令包示例，展示了如何在多个规则中复用命令序列：</p><div class="language-makefile vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">makefile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 定义一个编译C文件的命令包</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> compile-c</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> $(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CFLAGS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -c </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -o </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endef</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 定义一个链接目标文件的命令包</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">define</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> link-binary</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> $(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LDFLAGS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $^</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> -o </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$@</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endef</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用命令包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: main.o utils.o</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">link-binary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">main.o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: main.c</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">compile-c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">utils.o</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: utils.c</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">compile-c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>在这个例子中，我们定义了两个命令包：</p><ul><li><code>compile-c</code>：用于编译C源文件为目标文件</li><li><code>link-binary</code>：用于链接目标文件生成可执行文件</li></ul><p>这样可以避免重复书写相似的编译和链接命令。</p>`,26)])])}const g=a(l,[["render",p]]);export{o as __pageData,g as default};
